CREATE TABLE activity_intervals (
  org_id uuid NOT NULL REFERENCES organizations(id),
  installation_id uuid NOT NULL,
  event_id uuid NOT NULL,
  span tstzrange NOT NULL,
  active_ranges tstzmultirange NOT NULL,
  runtime_ms bigint NOT NULL DEFAULT 0 CHECK (runtime_ms >= 0),
  app_version varchar(64) NOT NULL,
  PRIMARY KEY (org_id,installation_id,event_id),
  FOREIGN KEY (org_id, installation_id) REFERENCES installations(org_id, id),
  CHECK (NOT isempty(span) AND lower(span) IS NOT NULL AND upper(span) IS NOT NULL AND upper(span)-lower(span) <= interval '60 seconds' AND lower_inc(span) AND NOT upper_inc(span)),
  CHECK (active_ranges <@ tstzmultirange(span)),
  CHECK (runtime_ms <= extract(epoch FROM upper(span)-lower(span))*1000)
) ;
COMMENT ON TABLE activity_intervals IS '明细窗口内的分钟活动事实';
COMMENT ON COLUMN activity_intervals.org_id IS '组织隔离键';
COMMENT ON COLUMN activity_intervals.installation_id IS '安装';
COMMENT ON COLUMN activity_intervals.event_id IS '来源事件';
COMMENT ON COLUMN activity_intervals.span IS '[start,end)，最长一分钟';
COMMENT ON COLUMN activity_intervals.active_ranges IS '该分钟可信有效活动区间';
COMMENT ON COLUMN activity_intervals.runtime_ms IS '非休眠运行时长';
COMMENT ON COLUMN activity_intervals.app_version IS '版本';

