  status text NOT NULL CHECK (status IN ('accepted','queued','running','completed','failed','cancelled','interrupted')),
  revision integer NOT NULL DEFAULT 1 CHECK (revision > 0),
  app_version varchar(64) NOT NULL,
  PRIMARY KEY (org_id,installation_id,id),
  UNIQUE (org_id,installation_id,command_id),
  FOREIGN KEY (org_id, installation_id) REFERENCES installations(org_id, id)
) ;
COMMENT ON TABLE queries IS '逻辑提交事实；状态按 revision 更新';
COMMENT ON COLUMN queries.org_id IS '组织隔离键';
COMMENT ON COLUMN queries.installation_id IS '安装';
COMMENT ON COLUMN queries.id IS 'query_id';
COMMENT ON COLUMN queries.command_id IS '本地命令唯一键';
COMMENT ON COLUMN queries.accepted_at IS '接收时间';
COMMENT ON COLUMN queries.source IS '来源';
COMMENT ON COLUMN queries.trigger IS '触发者';
COMMENT ON COLUMN queries.status IS '状态';
COMMENT ON COLUMN queries.revision IS '乐观锁版本';
COMMENT ON COLUMN queries.app_version IS '提交版本';

CREATE TABLE runs (
  org_id uuid NOT NULL REFERENCES organizations(id),
  installation_id uuid NOT NULL,
  id uuid NOT NULL,
  query_id uuid,
  parent_run_id uuid,
  source varchar(32) NOT NULL,
  started_at timestamptz,
  finished_at timestamptz,
  status text NOT NULL CHECK (status IN ('running','completed','failed','cancelled','interrupted')),
  duration_ms bigint CHECK (duration_ms >= 0),
  waiting_ms bigint CHECK (waiting_ms >= 0),
  app_version varchar(64) NOT NULL,
  PRIMARY KEY (org_id,installation_id,id),
  FOREIGN KEY (org_id, installation_id) REFERENCES installations(org_id, id),
  CHECK (finished_at IS NULL OR started_at IS NULL OR finished_at >= started_at)
) ;
COMMENT ON TABLE runs IS '任务事实；未知耗时保留空值';
COMMENT ON COLUMN runs.org_id IS '组织隔离键';
COMMENT ON COLUMN runs.installation_id IS '安装';
COMMENT ON COLUMN runs.id IS 'run_id';
COMMENT ON COLUMN runs.query_id IS '可空归属 Query；允许乱序到达';
COMMENT ON COLUMN runs.parent_run_id IS '父任务';
COMMENT ON COLUMN runs.source IS '来源';
COMMENT ON COLUMN runs.started_at IS '开始时间';
COMMENT ON COLUMN runs.finished_at IS '可信结束时间';
COMMENT ON COLUMN runs.status IS 'running/终态';
COMMENT ON COLUMN runs.duration_ms IS '任务耗时';
COMMENT ON COLUMN runs.waiting_ms IS '人工等待耗时';
COMMENT ON COLUMN runs.app_version IS '版本';

CREATE TABLE model_calls (
  org_id uuid NOT NULL REFERENCES organizations(id),
  installation_id uuid NOT NULL,
  id uuid NOT NULL,
  query_id uuid,
  run_id uuid,
  provider varchar(128) NOT NULL,
  model varchar(256) NOT NULL,
  source varchar(32) NOT NULL,
  status text NOT NULL CHECK (status IN ('running','completed','failed','cancelled','interrupted')),
  started_at timestamptz NOT NULL,
  finished_at timestamptz,
  duration_ms bigint CHECK (duration_ms >= 0),
  usage_status text NOT NULL CHECK (usage_status IN ('reported','partial','unavailable')),
  input_tokens bigint CHECK (input_tokens >= 0),
  output_tokens bigint CHECK (output_tokens >= 0),
  cache_read_tokens bigint CHECK (cache_read_tokens >= 0),
  cache_write_tokens bigint CHECK (cache_write_tokens >= 0),
  total_tokens bigint CHECK (total_tokens >= 0),
  app_version varchar(64) NOT NULL,
  PRIMARY KEY (org_id,installation_id,id),
  FOREIGN KEY (org_id, installation_id) REFERENCES installations(org_id, id),
  CHECK (finished_at IS NULL OR finished_at >= started_at),
  CHECK (usage_status <> 'unavailable' OR (input_tokens IS NULL AND output_tokens IS NULL AND cache_read_tokens IS NULL AND cache_write_tokens IS NULL AND total_tokens IS NULL))
) ;
COMMENT ON TABLE model_calls IS '每次实际供应商调用；含重试/辅助调用';
COMMENT ON COLUMN model_calls.org_id IS '组织隔离键';
COMMENT ON COLUMN model_calls.installation_id IS '安装';
COMMENT ON COLUMN model_calls.id IS 'call_id';
COMMENT ON COLUMN model_calls.query_id IS '冻结归属，允许空及乱序';
COMMENT ON COLUMN model_calls.run_id IS '任务';
COMMENT ON COLUMN model_calls.provider IS '供应商';
COMMENT ON COLUMN model_calls.model IS '实际模型';
COMMENT ON COLUMN model_calls.source IS '来源';
COMMENT ON COLUMN model_calls.status IS 'running/终态';
COMMENT ON COLUMN model_calls.started_at IS '开始';
COMMENT ON COLUMN model_calls.finished_at IS '结束';
COMMENT ON COLUMN model_calls.duration_ms IS '耗时';
COMMENT ON COLUMN model_calls.usage_status IS '用量完整性';
COMMENT ON COLUMN model_calls.input_tokens IS '归一化用量；未知为 NULL';
COMMENT ON COLUMN model_calls.output_tokens IS '归一化用量；未知为 NULL';
COMMENT ON COLUMN model_calls.cache_read_tokens IS '归一化用量；未知为 NULL';
COMMENT ON COLUMN model_calls.cache_write_tokens IS '归一化用量；未知为 NULL';
COMMENT ON COLUMN model_calls.total_tokens IS '归一化用量；未知为 NULL';
COMMENT ON COLUMN model_calls.app_version IS '版本';

CREATE TABLE file_changes (
  org_id uuid NOT NULL REFERENCES organizations(id),
  installation_id uuid NOT NULL,
  id uuid NOT NULL,
  query_id uuid,
  run_id uuid,
  tool_call_id varchar(256) NOT NULL,
  file_key char(64) NOT NULL,
  language varchar(80) NOT NULL,
  file_category text NOT NULL CHECK (file_category IN ('code','config','document','other')),
  kind text NOT NULL CHECK (kind IN ('created','updated','unchanged','unknown')),
  added_lines bigint CHECK (added_lines >= 0),
  deleted_lines bigint CHECK (deleted_lines >= 0),
  measurement_status text NOT NULL,
  occurred_at timestamptz NOT NULL,
  source varchar(32) NOT NULL,
  app_version varchar(64) NOT NULL,
  PRIMARY KEY (org_id,installation_id,id),
  FOREIGN KEY (org_id, installation_id) REFERENCES installations(org_id, id),
  CHECK (file_key ~ '^[a-f0-9]{64}$'),
  CHECK (measurement_status IN ('measured','unsupported','too_large','binary','unreadable','concurrent_change','failed')),
  CHECK ((measurement_status = 'measured' AND added_lines IS NOT NULL AND deleted_lines IS NOT NULL) OR (measurement_status <> 'measured' AND added_lines IS NULL AND deleted_lines IS NULL))
) ;
COMMENT ON TABLE file_changes IS '可靠文件工具操作事实，不保存文件路径/代码';
COMMENT ON COLUMN file_changes.org_id IS '组织隔离键';
COMMENT ON COLUMN file_changes.installation_id IS '安装';
COMMENT ON COLUMN file_changes.id IS 'operation_id';
COMMENT ON COLUMN file_changes.query_id IS '冻结 Query 归属';
COMMENT ON COLUMN file_changes.run_id IS '任务';
COMMENT ON COLUMN file_changes.tool_call_id IS '本地工具 ID';
COMMENT ON COLUMN file_changes.file_key IS '本地随机密钥 HMAC 路径';
COMMENT ON COLUMN file_changes.language IS '语言';
COMMENT ON COLUMN file_changes.file_category IS '文件类别';
COMMENT ON COLUMN file_changes.kind IS 'created/updated/unchanged/unknown';
COMMENT ON COLUMN file_changes.added_lines IS '新增';
COMMENT ON COLUMN file_changes.deleted_lines IS '删除';
COMMENT ON COLUMN file_changes.measurement_status IS 'measured 等协议状态';
COMMENT ON COLUMN file_changes.occurred_at IS '执行结束时间';
COMMENT ON COLUMN file_changes.source IS '由 run/query 关联补充；未知为 system';
COMMENT ON COLUMN file_changes.app_version IS '版本';

CREATE TABLE installation_daily_metrics (
  org_id uuid NOT NULL REFERENCES organizations(id),
  installation_id uuid NOT NULL,
  day date NOT NULL,
  source varchar(32) NOT NULL,
  app_version varchar(64) NOT NULL,
  queries bigint NOT NULL DEFAULT 0 CHECK (queries >= 0),
  completed_queries bigint NOT NULL DEFAULT 0 CHECK (completed_queries >= 0),
  failed_queries bigint NOT NULL DEFAULT 0 CHECK (failed_queries >= 0),
  cancelled_queries bigint NOT NULL DEFAULT 0 CHECK (cancelled_queries >= 0),
  interrupted_queries bigint NOT NULL DEFAULT 0 CHECK (interrupted_queries >= 0),
  pending_queries bigint NOT NULL DEFAULT 0 CHECK (pending_queries >= 0),
  opens bigint NOT NULL DEFAULT 0 CHECK (opens >= 0),
  launches bigint NOT NULL DEFAULT 0 CHECK (launches >= 0),
  unknown_task_runs bigint NOT NULL DEFAULT 0 CHECK (unknown_task_runs >= 0),
  model_calls bigint NOT NULL DEFAULT 0 CHECK (model_calls >= 0),
  added_lines bigint NOT NULL DEFAULT 0 CHECK (added_lines >= 0),
  deleted_lines bigint NOT NULL DEFAULT 0 CHECK (deleted_lines >= 0),
  files_created bigint NOT NULL DEFAULT 0 CHECK (files_created >= 0),
  file_operations bigint NOT NULL DEFAULT 0 CHECK (file_operations >= 0),
  known_model_calls bigint NOT NULL DEFAULT 0 CHECK (known_model_calls >= 0),
  unknown_model_calls bigint NOT NULL DEFAULT 0 CHECK (unknown_model_calls >= 0),
  measured_file_operations bigint NOT NULL DEFAULT 0 CHECK (measured_file_operations >= 0),
  unmeasured_file_operations bigint NOT NULL DEFAULT 0 CHECK (unmeasured_file_operations >= 0),
  task_ms bigint CHECK (task_ms >= 0),
  input_tokens bigint CHECK (input_tokens >= 0),
  output_tokens bigint CHECK (output_tokens >= 0),
  cache_read_tokens bigint CHECK (cache_read_tokens >= 0),
  cache_write_tokens bigint CHECK (cache_write_tokens >= 0),
  total_tokens bigint CHECK (total_tokens >= 0),
  aggregated_at timestamptz NOT NULL,
  quality_codes text[] NOT NULL DEFAULT ARRAY[]::text[],
  PRIMARY KEY (org_id,installation_id,day,source,app_version),
  FOREIGN KEY (org_id, installation_id) REFERENCES installations(org_id, id)
) ;
COMMENT ON TABLE installation_daily_metrics IS '24 月可重映射的安装×日期×来源×版本汇总';
