COMMENT ON COLUMN installation_daily_metrics.day IS '北京时间自然日';
COMMENT ON COLUMN installation_daily_metrics.source IS '调用/事件来源';
COMMENT ON COLUMN installation_daily_metrics.app_version IS '发生时版本';
COMMENT ON COLUMN installation_daily_metrics.queries IS '同名 API 指标；允许求和';
COMMENT ON COLUMN installation_daily_metrics.completed_queries IS '同名 API 指标；允许求和';
COMMENT ON COLUMN installation_daily_metrics.failed_queries IS '同名 API 指标；允许求和';
COMMENT ON COLUMN installation_daily_metrics.cancelled_queries IS '同名 API 指标；允许求和';
COMMENT ON COLUMN installation_daily_metrics.interrupted_queries IS '同名 API 指标；允许求和';
COMMENT ON COLUMN installation_daily_metrics.pending_queries IS '同名 API 指标；允许求和';
COMMENT ON COLUMN installation_daily_metrics.opens IS '同名 API 指标；允许求和';
COMMENT ON COLUMN installation_daily_metrics.launches IS '同名 API 指标；允许求和';
COMMENT ON COLUMN installation_daily_metrics.unknown_task_runs IS '同名 API 指标；允许求和';
COMMENT ON COLUMN installation_daily_metrics.model_calls IS '同名 API 指标；允许求和';
COMMENT ON COLUMN installation_daily_metrics.added_lines IS '同名 API 指标；允许求和';
COMMENT ON COLUMN installation_daily_metrics.deleted_lines IS '同名 API 指标；允许求和';
COMMENT ON COLUMN installation_daily_metrics.files_created IS '同名 API 指标；允许求和';
COMMENT ON COLUMN installation_daily_metrics.file_operations IS '同名 API 指标；允许求和';
COMMENT ON COLUMN installation_daily_metrics.known_model_calls IS '同名 API 指标；允许求和';
COMMENT ON COLUMN installation_daily_metrics.unknown_model_calls IS '同名 API 指标；允许求和';
COMMENT ON COLUMN installation_daily_metrics.measured_file_operations IS '同名 API 指标；允许求和';
COMMENT ON COLUMN installation_daily_metrics.unmeasured_file_operations IS '同名 API 指标；允许求和';
COMMENT ON COLUMN installation_daily_metrics.task_ms IS '已知任务耗时和';
COMMENT ON COLUMN installation_daily_metrics.input_tokens IS '归一化用量；未知为 NULL';
COMMENT ON COLUMN installation_daily_metrics.output_tokens IS '归一化用量；未知为 NULL';
COMMENT ON COLUMN installation_daily_metrics.cache_read_tokens IS '归一化用量；未知为 NULL';
COMMENT ON COLUMN installation_daily_metrics.cache_write_tokens IS '归一化用量；未知为 NULL';
COMMENT ON COLUMN installation_daily_metrics.total_tokens IS '归一化用量；未知为 NULL';
COMMENT ON COLUMN installation_daily_metrics.aggregated_at IS '聚合时间';
