COMMENT ON COLUMN employee_domain_accounts.account_name IS '规范化域账号';
COMMENT ON COLUMN employee_domain_accounts.employee_id IS '员工';
COMMENT ON COLUMN employee_domain_accounts.created_at IS '创建时间';
-- 维护任务每月提前创建未来两个月；不使用 default 分区掩盖故障。
DO $$
DECLARE m timestamptz; partition_name text;
BEGIN
  FOR offset_month IN -1..2 LOOP
    m := date_trunc('month', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC' + (offset_month || ' months')::interval;
    partition_name := 'telemetry_events_' || to_char(m AT TIME ZONE 'UTC','YYYYMM');
    EXECUTE format('CREATE TABLE %I PARTITION OF telemetry_events FOR VALUES FROM (%L) TO (%L)',partition_name,m,m+interval '1 month');
  END LOOP;
END $$;
CREATE INDEX receipts_expiry ON event_receipts(expires_at);
CREATE INDEX events_installation_time ON telemetry_events(org_id,installation_id,occurred_at);
CREATE INDEX events_payload_lookup ON telemetry_events USING gin ((payload->'payload') jsonb_path_ops);
CREATE INDEX events_query_revision ON telemetry_events(org_id,installation_id,((payload->'payload')->>'query_id')) WHERE event_type='query.updated';
CREATE INDEX events_run_lookup ON telemetry_events(org_id,installation_id,((payload->'payload')->>'run_id')) WHERE event_type IN ('run.started','run.finished');
CREATE INDEX jobs_pending ON aggregation_jobs(available_at,lease_until) WHERE completed_revision < requested_revision;
CREATE INDEX queries_time ON queries(org_id,accepted_at DESC,id);
CREATE INDEX calls_time ON model_calls(org_id,started_at DESC,id);
CREATE INDEX calls_query ON model_calls(org_id,installation_id,query_id);
CREATE INDEX file_query ON file_changes(org_id,installation_id,query_id);
CREATE INDEX files_time ON file_changes(org_id,occurred_at);
CREATE INDEX bindings_employee ON installation_bindings(org_id,employee_id);
CREATE INDEX audit_time ON audit_logs(org_id,occurred_at DESC,id);
CREATE INDEX export_owner ON export_jobs(org_id,account_id,created_at DESC);
CREATE INDEX active_daily_day ON installation_daily_activity(org_id,day);
CREATE INDEX metrics_daily_day ON installation_daily_metrics(org_id,day,source);
CREATE INDEX models_daily_day ON installation_daily_models(org_id,day,provider,model);
CREATE INDEX files_daily_day ON daily_file_keys(org_id,day,file_category);
COMMIT;
